use crate::Result;
use clap::Parser;
use distributed_verification::{
    SerFunction,
    diff::{KaniListJson, MergeHashKaniList},
    logger,
};
use std::{
    collections::HashMap,
    path::{Path, PathBuf},
};

pub fn run(args: &[String]) -> Result<()> {
    logger::init();
    SubCmdMerge::parse_from(args).run()
}

/// `verify_rust_std merge` subcommand
#[derive(Parser, Debug)]
struct SubCmdMerge {
    /// A path to hash json file which is generated by distributed-verification.
    /// The path can point to a folder or a json file.
    /// When it's a folder path, all json fields are read and merged.
    #[arg(long)]
    hash_json: PathBuf,

    /// Strip file path prefix in hash json.
    #[arg(long, default_value_t)]
    strip_hash_json_prefix: String,

    /// A path to kani-list.json which is generated by kani.
    #[arg(long)]
    kani_list: String,

    /// Strip file path prefix in kani-list.
    #[arg(long, default_value_t)]
    strip_kani_list_prefix: String,
}

impl SubCmdMerge {
    fn run(self) -> Result<()> {
        debug!(?self);

        let mut v_hash_json = read_json(&self.hash_json)?;

        let mut kani_list: KaniListJson = crate::read_json(&self.kani_list)?;
        // normalize paths like core/src/../../portable-simd/crates/core_simd/src/masks.rs
        kani_list.normalize_file_path();

        if !self.strip_kani_list_prefix.is_empty() {
            kani_list.strip_path_prefix_raw(&self.strip_kani_list_prefix);
        }

        // The file field in hash.json is absolute, so to keep it simple, strip a prefix.
        let mut hash_map = HashMap::with_capacity(v_hash_json.iter().map(|h| h.1.len()).sum());
        for (crate_name, v_func) in &mut v_hash_json {
            let crate_name = &**crate_name;
            for func in v_func {
                let file =
                    func.file.strip_prefix(&self.strip_hash_json_prefix).unwrap_or(&func.file);
                let fn_name = &*func.name;
                let value = (crate_name, &*func.hash, func.proof_kind);
                hash_map.insert((file, fn_name), value);
            }
        }

        // Merge hash value by fn name.
        let cap = kani_list.totals.standard_harnesses + kani_list.totals.contract_harnesses;
        let mut v_merge = Vec::with_capacity(cap);
        for file_func in kani_list.file_func_name() {
            let (file, func) = file_func;
            let (crate_name, hash, proof_kind) = match hash_map.get(&file_func) {
                Some((crate_name, hash, proof_kind)) => {
                    (Some((*crate_name).into()), Some((*hash).into()), *proof_kind)
                }
                None => (None, None, None),
            };
            v_merge.push(MergeHashKaniList {
                krate: crate_name,
                file: file.into(),
                func: func.into(),
                hash,
                proof_kind,
            });
        }
        v_merge.sort_unstable();

        serde_json::to_writer_pretty(std::io::stdout(), &v_merge)?;

        Ok(())
    }
}

#[allow(clippy::type_complexity)]
fn read_json(path: &Path) -> Result<Vec<(Box<str>, Box<[SerFunction]>)>> {
    let mut v = Vec::new();

    let mut push_crate_fns = |p: &Path| {
        if p.extension().map(|ext| ext.as_encoded_bytes()) != Some(b"json") {
            return;
        }
        // NOTE: extract crate_name from crate_name.json, since we don't store crate_name in data.
        let crate_name = p.file_stem().unwrap().to_str().unwrap().into();
        let Ok(hash_json) = crate::read_json::<Box<[SerFunction]>>(p.to_str().unwrap()) else {
            return;
        };
        v.push((crate_name, hash_json));
    };

    if path.is_dir() {
        for entry in path.read_dir()? {
            let entry = entry?;
            if entry.file_type()?.is_file() {
                let json_file = entry.path();
                let _span = error_span!("json_paths", ?json_file).entered();
                push_crate_fns(&json_file);
            }
        }
    } else if path.is_file() {
        push_crate_fns(path);
    }

    Ok(v)
}
